-- StockPilot (PS2). If the starter's own ps2 seed differs, keep its columns and adjust lib/inventory.ts.
create table if not exists suppliers (id bigint generated by default as identity primary key, name text not null unique, contact_email text, lead_time_days int not null default 2);
create table if not exists products (
  id bigint generated by default as identity primary key, sku text unique not null, name text not null, category text not null,
  supplier_id bigint not null references suppliers(id), unit_cost numeric(10,2) not null check (unit_cost > 0),
  stock_qty int not null check (stock_qty >= 0), reorder_level int not null check (reorder_level >= 0),
  reorder_qty int not null check (reorder_qty > 0), avg_daily_sales numeric(8,2) not null default 0);
create table if not exists purchase_orders (id bigint generated by default as identity primary key, supplier_id bigint not null references suppliers(id),
  status text not null default 'draft' check (status in ('draft','approved','cancelled')), total_cost numeric(12,2) not null default 0, created_at timestamptz not null default now());
create table if not exists purchase_order_items (id bigint generated by default as identity primary key, po_id bigint not null references purchase_orders(id) on delete cascade,
  product_id bigint not null references products(id), qty int not null check (qty > 0), unit_cost numeric(10,2) not null);
alter table suppliers enable row level security; alter table products enable row level security;
alter table purchase_orders enable row level security; alter table purchase_order_items enable row level security;

